const { Text, Title, Paragraph } = Typography
const { TextArea } = Input
const { Option } = Select

// Super admin emails - fallback list (primary method is isSuperAdmin field in Firestore)
const SUPER_ADMIN_EMAILS = [
  'alonsdale@bernoullitechnologies.net',
  'tonylonsdale@bernoullitechnologies.net',
  'alons3253@gmail.com',
]

// Known collections in the database
const KNOWN_COLLECTIONS = ['users', 'sessions', 'counties']

// Memoized stat card component
const StatCard = memo(function StatCard({ title, value, prefix, valueStyle, suffix }) {
  return (
    <Card className={styles.statCard}>
      <Statistic
        title={title}
        value={value}
        prefix={prefix}
        valueStyle={valueStyle}
        suffix={suffix}
      />
    </Card>
  )
})

// Document viewer/editor modal
const DocumentModal = memo(function DocumentModal({
  visible,
  onClose,
  document,
  collectionName,
  documentId,
  onSave,
  onDelete,
  isNew,
}) {
  const [editedContent, setEditedContent] = useState('')
  const [isEditing, setIsEditing] = useState(isNew)
  const [saving, setSaving] = useState(false)

  useEffect(() => {
    if (document) {
      setEditedContent(JSON.stringify(document, null, 2))
    } else if (isNew) {
      setEditedContent('{\n  \n}')
    }
  }, [document, isNew])

  const handleSave = async () => {
    try {
      const parsed = JSON.parse(editedContent)
      setSaving(true)
      await onSave(parsed)
      setSaving(false)
      setIsEditing(false)
      message.success(isNew ? 'Document created successfully' : 'Document updated successfully')
    } catch (error) {
      if (error instanceof SyntaxError) {
        message.error('Invalid JSON format')
      } else {
        message.error('Failed to save document: ' + error.message)
      }
      setSaving(false)
    }
  }

  return (
    <Modal
      title={
        <Space>
          <DatabaseOutlined />
          <span>{isNew ? 'Create New Document' : `Document: ${documentId}`}</span>
          {!isNew && (
            <Tag color="blue">{collectionName}</Tag>
          )}
        </Space>
      }
      open={visible}
      onCancel={onClose}
      width={800}
      footer={[
        <Button key="cancel" onClick={onClose}>
          Cancel
        </Button>,
        !isNew && !isEditing && (
          <Button key="edit" icon={<EditOutlined />} onClick={() => setIsEditing(true)}>
            Edit
          </Button>
        ),
        isEditing && (
          <Button key="save" type="primary" icon={<SaveOutlined />} loading={saving} onClick={handleSave}>
            {isNew ? 'Create' : 'Save Changes'}
          </Button>
        ),
        !isNew && (
          <Popconfirm
            key="delete"
            title="Delete this document?"
            description="This action cannot be undone."
            onConfirm={onDelete}
            okText="Delete"
            cancelText="Cancel"
            okButtonProps={{ danger: true }}
          >
            <Button danger icon={<DeleteOutlined />}>
              Delete
            </Button>
          </Popconfirm>
        ),
      ].filter(Boolean)}
    >
      {isEditing ? (
        <TextArea
          value={editedContent}
          onChange={(e) => setEditedContent(e.target.value)}
          rows={20}
          className={styles.jsonEditor}
          placeholder="Enter JSON document..."
        />
      ) : (
        <pre className={styles.jsonViewer}>
          {JSON.stringify(document, null, 2)}
        </pre>
      )}
    </Modal>
  )
})


function SuperAdminPanel({ visible, onClose, currentUser }) {
  const [activeTab, setActiveTab] = useState('overview')
  const [loading, setLoading] = useState(false)
  const [users, setUsers] = useState([])
  const [sessions, setSessions] = useState([])
  const [collections, setCollections] = useState([])
  const [selectedCollection, setSelectedCollection] = useState(null)
  const [collectionDocuments, setCollectionDocuments] = useState([])
  const [selectedDocument, setSelectedDocument] = useState(null)
  const [documentModalVisible, setDocumentModalVisible] = useState(false)
  const [isNewDocument, setIsNewDocument] = useState(false)
  const [newDocumentId, setNewDocumentId] = useState('')
  const [searchQuery, setSearchQuery] = useState('')
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalSessions: 0,
    activeSessions: 0,
    administrators: 0,
    superAdmins: 0,
    usersWithPlainTextPasswords: 0,
  })
  const functionsRef = useRef(null)

  // Check if current user is a super admin
  const isSuperAdmin = useMemo(() => {
    if (!currentUser) return false
    return SUPER_ADMIN_EMAILS.includes(currentUser.email?.toLowerCase())
  }, [currentUser])

  // Lazily initialize Firebase functions
  const getFunctionsRef = useCallback(() => {
    if (!functionsRef.current) {
      functionsRef.current = getFunctions()
    }
    return functionsRef.current
  }, [])

  // Fetch all users
  const fetchUsers = useCallback(async () => {
    if (!isSuperAdmin) return

    setLoading(true)
    try {
      const usersCollection = collection(db, 'users')
      const snapshot = await getDocs(usersCollection)
      const userList = []
      let plainTextCount = 0
      let adminCount = 0
      let superAdminCount = 0

      snapshot.forEach((docSnap) => {
        const data = docSnap.data()
        const hasPlainTextPassword = !!data.password
        if (hasPlainTextPassword) plainTextCount++
        if (data.isAdministrator) adminCount++
        if (data.isSuperAdmin) superAdminCount++

        userList.push({
          id: docSnap.id,
          email: data.email || 'N/A',
          username: data.username || 'N/A',
          hasPlainTextPassword,
          isAdministrator: data.isAdministrator || false,
          isSuperAdmin: data.isSuperAdmin || false,
          phoneNumber: data.phoneNumber || null,
          createdAt: data.createdAt || 'Unknown',
        })
      })

      setUsers(userList)
      setStats((prev) => ({
        ...prev,
        totalUsers: userList.length,
        usersWithPlainTextPasswords: plainTextCount,
        administrators: adminCount,
        superAdmins: superAdminCount,
      }))
    } catch (err) {
      console.error('Error fetching users:', err)
      message.error('Failed to fetch users')
    } finally {
      setLoading(false)
    }
  }, [isSuperAdmin])

  // Fetch all sessions
  const fetchSessions = useCallback(async () => {
    if (!isSuperAdmin) return

    try {
      const sessionsCollection = collection(db, 'sessions')
      const snapshot = await getDocs(sessionsCollection)
      const sessionList = []
      let activeCount = 0

      snapshot.forEach((docSnap) => {
        const data = docSnap.data()
        if (data.isValid) activeCount++

        sessionList.push({
          id: docSnap.id,
          ...data,
          createdAt: data.createdAt?.toDate?.()?.toLocaleString() || 'Unknown',
          lastActive: data.lastActive?.toDate?.()?.toLocaleString() || 'Unknown',
        })
      })

      setSessions(sessionList)
      setStats((prev) => ({
        ...prev,
        totalSessions: sessionList.length,
        activeSessions: activeCount,
      }))
    } catch (err) {
      console.error('Error fetching sessions:', err)
    }
  }, [isSuperAdmin])

  // Fetch collections
  const fetchCollections = useCallback(async () => {
    if (!isSuperAdmin) return

    // Since Firestore doesn't have a native listCollections for web,
    // we use our known collections list
    setCollections(KNOWN_COLLECTIONS.map((name) => ({
      name,
      icon: name === 'users' ? <TeamOutlined /> : name === 'sessions' ? <CloudServerOutlined /> : <FolderOpenOutlined />,
    })))
  }, [isSuperAdmin])

  // Fetch documents in a collection
  const fetchCollectionDocuments = useCallback(async (collectionName) => {
    if (!isSuperAdmin || !collectionName) return

    setLoading(true)
    try {
      const collRef = collection(db, collectionName)
      const snapshot = await getDocs(collRef)
      const docs = []

      snapshot.forEach((docSnap) => {
        const data = docSnap.data()
        docs.push({
          id: docSnap.id,
          data,
          preview: JSON.stringify(data).substring(0, 100) + '...',
        })
      })

      setCollectionDocuments(docs)
      setSelectedCollection(collectionName)
    } catch (err) {
      console.error('Error fetching collection documents:', err)
      message.error('Failed to fetch documents')
    } finally {
      setLoading(false)
    }
  }, [isSuperAdmin])

  // Toggle admin status
  const toggleAdminStatus = useCallback(async (userId, currentStatus) => {
    try {
      const userRef = doc(db, 'users', userId)
      await updateDoc(userRef, {
        isAdministrator: !currentStatus,
      })
      message.success(`User ${!currentStatus ? 'promoted to' : 'removed from'} administrator`)
      fetchUsers()
    } catch (err) {
      console.error('Error updating admin status:', err)
      message.error('Failed to update admin status')
    }
  }, [fetchUsers])

  // Remove plain text password
  const removePasswordFromUser = useCallback(async (userId) => {
    try {
      const userRef = doc(db, 'users', userId)
      await updateDoc(userRef, {
        password: deleteField(),
      })
      message.success('Plain text password removed')
      fetchUsers()
    } catch (err) {
      console.error('Error removing password:', err)
      message.error('Failed to remove password')
    }
  }, [fetchUsers])

  // Clean all plain text passwords using batch writes for better performance
  const cleanAllPlainTextPasswords = useCallback(async () => {
    setLoading(true)
    try {
      const usersWithPasswords = users.filter((u) => u.hasPlainTextPassword)

      // Use batch writes for better performance and atomicity (max 500 per batch)
      const batchSize = 500
      let cleaned = 0

      for (let i = 0; i < usersWithPasswords.length; i += batchSize) {
        const batch = writeBatch(db)
        const chunk = usersWithPasswords.slice(i, i + batchSize)

        chunk.forEach((user) => {
          const userRef = doc(db, 'users', user.id)
          batch.update(userRef, { password: deleteField() })
        })

        await batch.commit()
        cleaned += chunk.length
      }

      message.success(`Removed ${cleaned} plain text password(s)`)
      fetchUsers()
    } catch (err) {
      console.error('Error cleaning passwords:', err)
      message.error('Failed to clean passwords')
    } finally {
      setLoading(false)
    }
  }, [users, fetchUsers])

  // Invalidate a session
  const invalidateSession = useCallback(async (sessionId, userId) => {
    try {
      const functions = getFunctionsRef()
      const invalidateSessionFn = httpsCallable(functions, 'invalidateSession')
      await invalidateSessionFn({ sessionId })
      message.success('Session invalidated')
      fetchSessions()
    } catch (err) {
      console.error('Error invalidating session:', err)
      message.error('Failed to invalidate session')
    }
  }, [getFunctionsRef, fetchSessions])

  // Delete a document
  const deleteDocument = useCallback(async (collectionName, documentId) => {
    try {
      const docRef = doc(db, collectionName, documentId)
      await deleteDoc(docRef)
      message.success('Document deleted')
      fetchCollectionDocuments(collectionName)
      setDocumentModalVisible(false)
    } catch (err) {
      console.error('Error deleting document:', err)
      message.error('Failed to delete document')
    }
  }, [fetchCollectionDocuments])

  // Save/update a document
  const saveDocument = useCallback(async (collectionName, documentId, data) => {
    try {
      const docRef = doc(db, collectionName, documentId)
      await setDoc(docRef, data, { merge: true })
      fetchCollectionDocuments(collectionName)
      setDocumentModalVisible(false)
    } catch (err) {
      console.error('Error saving document:', err)
      throw err
    }
  }, [fetchCollectionDocuments])

  // Create new document
  const handleCreateDocument = useCallback(() => {
    if (!selectedCollection) {
      message.warning('Please select a collection first')
      return
    }
    setIsNewDocument(true)
    setSelectedDocument(null)
    setNewDocumentId('')
    setDocumentModalVisible(true)
  }, [selectedCollection])

  // Initial data fetch
  useEffect(() => {
    if (visible && isSuperAdmin) {
      fetchUsers()
      fetchSessions()
      fetchCollections()
    }
  }, [visible, isSuperAdmin, fetchUsers, fetchSessions, fetchCollections])

  // User management columns
  const userColumns = useMemo(() => [
    {
      title: 'Username',
      dataIndex: 'username',
      key: 'username',
      sorter: (a, b) => a.username.localeCompare(b.username),
      filteredValue: searchQuery ? [searchQuery] : null,
      onFilter: (value, record) =>
        record.username.toLowerCase().includes(value.toLowerCase()) ||
        record.email.toLowerCase().includes(value.toLowerCase()),
    },
    {
      title: 'Email',
      dataIndex: 'email',
      key: 'email',
      sorter: (a, b) => a.email.localeCompare(b.email),
    },
    {
      title: 'Status',
      key: 'status',
      render: (_, record) => (
        <Space wrap>
          {record.hasPlainTextPassword && (
            <Tag color="red" icon={<ExclamationCircleOutlined />}>
              VULNERABLE
            </Tag>
          )}
          {record.isSuperAdmin && <Tag color="purple">Super Admin</Tag>}
          {record.isAdministrator && !record.isSuperAdmin && <Tag color="blue">Admin</Tag>}
          {!record.isAdministrator && !record.isSuperAdmin && <Tag color="default">User</Tag>}
        </Space>
      ),
      filters: [
        { text: 'Super Admin', value: 'superadmin' },
        { text: 'Admin', value: 'admin' },
        { text: 'User', value: 'user' },
        { text: 'Vulnerable', value: 'vulnerable' },
      ],
      onFilter: (value, record) => {
        if (value === 'superadmin') return record.isSuperAdmin
        if (value === 'admin') return record.isAdministrator && !record.isSuperAdmin
        if (value === 'user') return !record.isAdministrator && !record.isSuperAdmin
        if (value === 'vulnerable') return record.hasPlainTextPassword
        return true
      },
    },
    {
      title: 'Created',
      dataIndex: 'createdAt',
      key: 'createdAt',
      render: (date) => (date !== 'Unknown' ? new Date(date).toLocaleDateString() : 'Unknown'),
      sorter: (a, b) => new Date(a.createdAt) - new Date(b.createdAt),
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <Space>
          <Tooltip title={record.isAdministrator ? 'Remove Admin' : 'Make Admin'}>
            <Button
              type="text"
              icon={<UserSwitchOutlined />}
              onClick={() => toggleAdminStatus(record.id, record.isAdministrator)}
              disabled={record.isSuperAdmin}
            />
          </Tooltip>
          {record.hasPlainTextPassword && (
            <Tooltip title="Remove Plain Text Password">
              <Popconfirm
                title="Remove plain text password?"
                onConfirm={() => removePasswordFromUser(record.id)}
              >
                <Button type="text" danger icon={<SafetyOutlined />} />
              </Popconfirm>
            </Tooltip>
          )}
          <Tooltip title="View in Database">
            <Button
              type="text"
              icon={<EyeOutlined />}
              onClick={() => {
                setSelectedCollection('users')
                setSelectedDocument({ id: record.id, data: record })
                setIsNewDocument(false)
                setDocumentModalVisible(true)
              }}
            />
          </Tooltip>
        </Space>
      ),
    },
  ], [searchQuery, toggleAdminStatus, removePasswordFromUser])

  // Session columns
  const sessionColumns = useMemo(() => [
    {
      title: 'User ID',
      dataIndex: 'id',
      key: 'id',
      render: (id) => <Text copyable={{ text: id }}>{id.substring(0, 8)}...</Text>,
    },
    {
      title: 'Device',
      dataIndex: 'device',
      key: 'device',
    },
    {
      title: 'Browser',
      dataIndex: 'browser',
      key: 'browser',
    },
    {
      title: 'IP Address',
      dataIndex: 'ip',
      key: 'ip',
    },
    {
      title: 'Status',
      dataIndex: 'isValid',
      key: 'isValid',
      render: (isValid) => (
        <Badge status={isValid ? 'success' : 'default'} text={isValid ? 'Active' : 'Expired'} />
      ),
    },
    {
      title: 'Created',
      dataIndex: 'createdAt',
      key: 'createdAt',
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <Space>
          {record.isValid && (
            <Popconfirm
              title="Invalidate this session?"
              onConfirm={() => invalidateSession(record.sessionId, record.id)}
            >
              <Button type="text" danger size="small">
                Terminate
              </Button>
            </Popconfirm>
          )}
        </Space>
      ),
    },
  ], [invalidateSession])

  // Document columns
  const documentColumns = useMemo(() => [
    {
      title: 'Document ID',
      dataIndex: 'id',
      key: 'id',
      render: (id) => <Text copyable={{ text: id }}>{id.substring(0, 20)}...</Text>,
    },
    {
      title: 'Preview',
      dataIndex: 'preview',
      key: 'preview',
      render: (preview) => <Text type="secondary">{preview}</Text>,
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <Space>
          <Button
            type="text"
            icon={<EyeOutlined />}
            onClick={() => {
              setSelectedDocument(record)
              setIsNewDocument(false)
              setDocumentModalVisible(true)
            }}
          >
            View
          </Button>
          <Popconfirm
            title="Delete this document?"
            onConfirm={() => deleteDocument(selectedCollection, record.id)}
          >
            <Button type="text" danger icon={<DeleteOutlined />}>
              Delete
            </Button>
          </Popconfirm>
        </Space>
      ),
    },
  ], [selectedCollection, deleteDocument])

  if (!isSuperAdmin) {
    return null
  }

  const tabItems = [
    {
      key: 'overview',
      label: (
        <span>
          <SettingOutlined />
          Overview
        </span>
      ),
      children: (
        <div className={styles.overviewTab}>
          <Row gutter={[16, 16]}>
            <Col xs={24} sm={12} md={6}>
              <StatCard
                title="Total Users"
                value={stats.totalUsers}
                prefix={<TeamOutlined />}
              />
            </Col>
            <Col xs={24} sm={12} md={6}>
              <StatCard
                title="Active Sessions"
                value={stats.activeSessions}
                prefix={<CloudServerOutlined />}
                valueStyle={{ color: '#3f8600' }}
              />
            </Col>
            <Col xs={24} sm={12} md={6}>
              <StatCard
                title="Administrators"
                value={stats.administrators}
                prefix={<UserOutlined />}
                valueStyle={{ color: '#1890ff' }}
              />
            </Col>
            <Col xs={24} sm={12} md={6}>
              <StatCard
                title="Security Issues"
                value={stats.usersWithPlainTextPasswords}
                prefix={<SafetyOutlined />}
                valueStyle={{ color: stats.usersWithPlainTextPasswords > 0 ? '#cf1322' : '#3f8600' }}
              />
            </Col>
          </Row>

          {stats.usersWithPlainTextPasswords > 0 && (
            <Alert
              message="Security Vulnerabilities Detected"
              description={
                <div>
                  <p>{stats.usersWithPlainTextPasswords} user(s) have passwords stored in plain text.</p>
                  <Popconfirm
                    title="Clean all plain text passwords?"
                    onConfirm={cleanAllPlainTextPasswords}
                  >
                    <Button type="primary" danger icon={<SafetyOutlined />} loading={loading}>
                      Remove All Plain Text Passwords
                    </Button>
                  </Popconfirm>
                </div>
              }
              type="error"
              showIcon
              className={styles.securityAlert}
            />
          )}

          <Divider>System Information</Divider>

          <Descriptions bordered column={{ xs: 1, sm: 2, md: 3 }}>
            <Descriptions.Item label="Firebase Project">leaddrive-pro</Descriptions.Item>
            <Descriptions.Item label="Total Sessions">{stats.totalSessions}</Descriptions.Item>
            <Descriptions.Item label="Super Admins">{stats.superAdmins}</Descriptions.Item>
            <Descriptions.Item label="Session Timeout">15 minutes</Descriptions.Item>
            <Descriptions.Item label="Login Lockout">5 attempts / 15 min</Descriptions.Item>
            <Descriptions.Item label="Session Validation">Every 10 minutes</Descriptions.Item>
          </Descriptions>
        </div>
      ),
    },
    {
      key: 'users',
      label: (
        <span>
          <TeamOutlined />
          User Management
        </span>
      ),
      children: (
        <div className={styles.usersTab}>
          <div className={styles.tableHeader}>
            <Space>
              <Input
                placeholder="Search users..."
                prefix={<SearchOutlined />}
                onChange={(e) => setSearchQuery(e.target.value)}
                style={{ width: 250 }}
                allowClear
              />
            </Space>
            <Button icon={<ReloadOutlined />} onClick={fetchUsers} loading={loading}>
              Refresh
            </Button>
          </div>
          <Table
            columns={userColumns}
            dataSource={users}
            rowKey="id"
            loading={loading}
            pagination={{ pageSize: 10, showSizeChanger: true }}
            scroll={{ x: 800 }}
          />
        </div>
      ),
    },
    {
      key: 'sessions',
      label: (
        <span>
          <CloudServerOutlined />
          Sessions
        </span>
      ),
      children: (
        <div className={styles.sessionsTab}>
          <div className={styles.tableHeader}>
            <Title level={5}>Active Sessions</Title>
            <Button icon={<ReloadOutlined />} onClick={fetchSessions}>
              Refresh
            </Button>
          </div>
          <Table
            columns={sessionColumns}
            dataSource={sessions}
            rowKey="id"
            loading={loading}
            pagination={{ pageSize: 10 }}
            scroll={{ x: 800 }}
          />
        </div>
      ),
    },
    {
      key: 'database',
      label: (
        <span>
          <DatabaseOutlined />
          Database Browser
        </span>
      ),
      children: (
        <div className={styles.databaseTab}>
          <Row gutter={16}>
            <Col xs={24} md={6}>
              <Card
                title="Collections"
                size="small"
                className={styles.collectionsCard}
                extra={
                  <Tooltip title="Refresh">
                    <Button type="text" icon={<ReloadOutlined />} onClick={fetchCollections} />
                  </Tooltip>
                }
              >
                <List
                  dataSource={collections}
                  renderItem={(item) => (
                    <List.Item
                      className={`${styles.collectionItem} ${selectedCollection === item.name ? styles.selected : ''}`}
                      onClick={() => fetchCollectionDocuments(item.name)}
                    >
                      <Space>
                        {item.icon}
                        <span>{item.name}</span>
                      </Space>
                    </List.Item>
                  )}
                />
              </Card>
            </Col>
            <Col xs={24} md={18}>
              <Card
                title={
                  <Space>
                    <span>Documents</span>
                    {selectedCollection && <Tag color="blue">{selectedCollection}</Tag>}
                  </Space>
                }
                size="small"
                extra={
                  <Space>
                    <Button
                      type="primary"
                      icon={<PlusOutlined />}
                      onClick={handleCreateDocument}
                      disabled={!selectedCollection}
                    >
                      New Document
                    </Button>
                    <Button
                      icon={<ReloadOutlined />}
                      onClick={() => fetchCollectionDocuments(selectedCollection)}
                      disabled={!selectedCollection}
                    />
                  </Space>
                }
              >
                {selectedCollection ? (
                  <Table
                    columns={documentColumns}
                    dataSource={collectionDocuments}
                    rowKey="id"
                    loading={loading}
                    pagination={{ pageSize: 10 }}
                    locale={{
                      emptyText: <Empty description="No documents in this collection" />,
                    }}
                  />
                ) : (
                  <Empty description="Select a collection to view documents" />
                )}
              </Card>
            </Col>
          </Row>
        </div>
      ),
    },
    {
      key: 'security',
      label: (
        <span>
          <SafetyOutlined />
          Security Audit
        </span>
      ),
      children: (
        <div className={styles.securityTab}>
          <Row gutter={[16, 16]}>
            <Col xs={24} md={12}>
              <Card title="Security Checklist" size="small">
                <Timeline
                  items={[
                    {
                      color: stats.usersWithPlainTextPasswords === 0 ? 'green' : 'red',
                      children: (
                        <span>
                          Plain text passwords: {stats.usersWithPlainTextPasswords === 0 ? 'None detected' : `${stats.usersWithPlainTextPasswords} found`}
                        </span>
                      ),
                    },
                    {
                      color: 'green',
                      children: 'Firebase Auth password hashing: Enabled',
                    },
                    {
                      color: 'green',
                      children: 'Session validation: Every 10 minutes',
                    },
                    {
                      color: 'green',
                      children: 'Inactivity timeout: 15 minutes',
                    },
                    {
                      color: 'green',
                      children: 'Login rate limiting: 5 attempts / 15 min lockout',
                    },
                  ]}
                />
              </Card>
            </Col>
            <Col xs={24} md={12}>
              <Card title="Vulnerable Accounts" size="small">
                {users.filter((u) => u.hasPlainTextPassword).length > 0 ? (
                  <List
                    size="small"
                    dataSource={users.filter((u) => u.hasPlainTextPassword)}
                    renderItem={(user) => (
                      <List.Item
                        actions={[
                          <Popconfirm
                            key="fix"
                            title="Remove plain text password?"
                            onConfirm={() => removePasswordFromUser(user.id)}
                          >
                            <Button type="link" danger size="small">
                              Fix
                            </Button>
                          </Popconfirm>,
                        ]}
                      >
                        <List.Item.Meta
                          avatar={<ExclamationCircleOutlined style={{ color: '#cf1322' }} />}
                          title={user.username}
                          description={user.email}
                        />
                      </List.Item>
                    )}
                  />
                ) : (
                  <Empty description="No vulnerable accounts" image={Empty.PRESENTED_IMAGE_SIMPLE} />
                )}
              </Card>
            </Col>
          </Row>
        </div>
      ),
    },
  ]

  return (
    <>
      <Modal
        title={
          <div className={styles.modalTitle}>
            <SafetyOutlined className={styles.titleIcon} />
            <span>Super Administrator Panel</span>
            <Tag color="purple">Full Access</Tag>
          </div>
        }
        open={visible}
        onCancel={onClose}
        footer={null}
        width={1200}
        className={styles.superAdminModal}
      >
        <Spin spinning={loading && activeTab === 'overview'}>
          <Tabs
            activeKey={activeTab}
            onChange={setActiveTab}
            items={tabItems}
            className={styles.tabs}
          />
        </Spin>
      </Modal>

      {documentModalVisible && (
        <DocumentModal
          visible={documentModalVisible}
          onClose={() => {
            setDocumentModalVisible(false)
            setSelectedDocument(null)
            setIsNewDocument(false)
          }}
          document={selectedDocument?.data}
          collectionName={selectedCollection}
          documentId={isNewDocument ? newDocumentId : selectedDocument?.id}
          isNew={isNewDocument}
          onSave={(data) => {
            if (isNewDocument) {
              const docId = newDocumentId || `doc_${Date.now()}`
              return saveDocument(selectedCollection, docId, data)
            }
            return saveDocument(selectedCollection, selectedDocument.id, data)
          }}
          onDelete={() => deleteDocument(selectedCollection, selectedDocument?.id)}
        />
      )}

      {isNewDocument && (
        <Modal
          title="Enter Document ID"
          open={isNewDocument && !selectedDocument && documentModalVisible}
          onOk={() => {
            if (!newDocumentId.trim()) {
              setNewDocumentId(`doc_${Date.now()}`)
            }
          }}
          onCancel={() => {
            setIsNewDocument(false)
            setDocumentModalVisible(false)
          }}
        >
          <Form layout="vertical">
            <Form.Item label="Document ID" help="Leave empty to auto-generate">
              <Input
                value={newDocumentId}
                onChange={(e) => setNewDocumentId(e.target.value)}
                placeholder="Enter document ID or leave empty"
              />
            </Form.Item>
          </Form>
        </Modal>
      )}
    </>
  )
}

export { SUPER_ADMIN_EMAILS }
export default memo(SuperAdminPanel)
