import { AppstoreOutlined, LoginOutlined } from '@ant-design/icons'
import { Image, Layout } from 'antd'
import { onAuthStateChanged } from 'firebase/auth'
import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Link } from 'react-router-dom'
import { auth } from '../auth/firebase.jsx'
import logo from '../images/logoblank.png'
import { debounce } from '../utils/helpers.js'
import HamburgerMenu from './HamburgerMenu.jsx'
import './CustomHeader.css'

const { Header } = Layout

// Memoized auth button to prevent re-renders
const AuthButton = memo(function AuthButton({ isAuthenticated }) {
  return (
    <Link
      to={isAuthenticated ? '/campaign-tools' : '/login'}
      className="header-auth-btn"
    >
      {isAuthenticated ? (
        <>
          <AppstoreOutlined className="header-auth-icon" />
          <span className="header-auth-text">Dashboard</span>
        </>
      ) : (
        <>
          <LoginOutlined className="header-auth-icon" />
          <span className="header-auth-text">Login</span>
        </>
      )}
    </Link>
  )
})

function CustomHeader() {
  const [visible, setVisible] = useState(true)
  const [isAuthenticated, setIsAuthenticated] = useState(false)
  const lastScrollTopRef = useRef(0)

  const handleScroll = useCallback(() => {
    const currentScrollPos = window.scrollY
    if (currentScrollPos > lastScrollTopRef.current && currentScrollPos > 0) {
      setVisible(false)
    } else {
      setVisible(true)
    }
    lastScrollTopRef.current = currentScrollPos <= 0 ? 0 : currentScrollPos
  }, [])

  // Memoize debounced scroll handler to prevent recreation
  const debouncedHandleScroll = useMemo(
      () => debounce(handleScroll, 50),
      [handleScroll],
  )

  useEffect(() => {
    window.addEventListener('scroll', debouncedHandleScroll, { passive: true })
    return () => {
      window.removeEventListener('scroll', debouncedHandleScroll)
    }
  }, [debouncedHandleScroll])

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setIsAuthenticated(!!user)
    })
    return () => unsubscribe()
  }, [])

  return (
    <Header className={`site-layout-background ${!visible && 'header-hidden'}`}>
      <Link to="/" className="logo-link">
        <Image src={logo} alt="Logo" className="header-logo" preview={false} />
        <div className="header-title">
          <span>Bernoulli&nbsp;</span>
          <span>Technologies</span>
        </div>
      </Link>
      <div className="header-right">
        <AuthButton isAuthenticated={isAuthenticated} />
        <HamburgerMenu />
      </div>
    </Header>
  )
}

export default memo(CustomHeader)
