import { CrownOutlined, DeploymentUnitOutlined, DollarOutlined, GlobalOutlined, HomeOutlined, NodeCollapseOutlined, SafetyOutlined, TeamOutlined } from '@ant-design/icons'
import { Button, Card, Col, Layout, Row, Typography } from 'antd'
import 'leaflet/dist/leaflet.css'
import React, { memo, useCallback, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { usePermissions } from '../auth/Permissions.jsx'
import Auth from '../auth/auth.jsx'
import CustomHeader from '../components/CustomHeader.jsx'
import AppFooter from '../components/Footer.jsx'
import Sidebar from '../components/SideBar.jsx'
import AdminPanel, { ADMIN_USERNAME } from '../modals/AdminPanel.jsx'
import SuperAdminPanel, { SUPER_ADMIN_EMAILS } from '../modals/SuperAdminPanel.jsx'
import styles from './CampaignTools.module.css'

const { Content } = Layout
const { Text } = Typography

// Shared icon style to avoid recreation
const iconStyle = { fontSize: '350%' }

// Centralized app configuration with icons and titles
const APP_CONFIG = {
  mapping: { icon: GlobalOutlined, title: 'Interactive Mapping Client' },
  doorknocking: { icon: HomeOutlined, title: 'Doorknocking Client' },
  electionsim: { icon: NodeCollapseOutlined, title: 'Election Simulator' },
  votercontacts: { icon: DeploymentUnitOutlined, title: 'Voter Contact Analysis' },
  fundraising: { icon: DollarOutlined, title: 'Fundraising Analytics' },
  volunteermgmt: { icon: TeamOutlined, title: 'Volunteer Management' },
  eventcoordination: { icon: TeamOutlined, title: 'Event Coordination' },
}

const applications = [
  { route: '/mapping', type: 'mapping', permissionKey: 'View Mapping Client' },
  { route: '/doorknocking', type: 'doorknocking', permissionKey: 'View Doorknocking Client' },
  { route: '/electionsim', type: 'electionsim', permissionKey: 'View Election Simulator' },
  { route: '/votercontacts', type: 'votercontacts', permissionKey: 'View Voter Contacts' },
  { route: '/fundraising', type: 'fundraising', permissionKey: 'View Fundraising Analytics' },
  { route: '/volunteermgmt', type: 'volunteermgmt', permissionKey: 'Volunteer Management' },
]

const EigApplications = [
  { route: '/eventcoordination', type: 'eventcoordination' },
]

// Memoized section separator component - moved outside main component
const SectionSeparator = memo(function SectionSeparator({ title }) {
  return (
    <div className={styles.sectionSeparator}>
      <Text className={styles.sectionTitle}>{title}</Text>
      <hr className={styles.sectionDivider} />
    </div>
  )
})

// Memoized card content component
const CardContent = memo(function CardContent({ title }) {
  return (
    <div className={styles.mappingClientContainer}>
      <Text className={styles.interactiveTitle}>{title}</Text>
    </div>
  )
})

// Memoized Eigel Apps card
const EigelApps = memo(function EigelApps({ app }) {
  const navigate = useNavigate()
  const { permissions } = usePermissions()
  const hasPermission = permissions['Can View Eigel Tools']

  const handleClick = useCallback(() => {
    if (hasPermission) {
      navigate(app.route)
    }
  }, [hasPermission, navigate, app.route])

  const config = APP_CONFIG[app.type]
  if (!config) return null

  const IconComponent = config.icon

  return (
    <Col xs={24} sm={12} md={10} lg={8} xl={8}>
      <Card
        hoverable={hasPermission}
        onClick={handleClick}
        className={hasPermission ? styles.applicationCard : styles.blurredCard}
      >
        <Card.Meta
          avatar={<IconComponent style={iconStyle} />}
          description={<CardContent title={config.title} />}
          className="card-meta"
        />
      </Card>
    </Col>
  )
})

// Memoized Application Card
const ApplicationCard = memo(function ApplicationCard({ app }) {
  const navigate = useNavigate()
  const { permissions } = usePermissions()
  const hasPermission = permissions[app.permissionKey]

  const handleClick = useCallback(() => {
    if (hasPermission) {
      navigate(app.route)
    }
  }, [hasPermission, navigate, app.route])

  const config = APP_CONFIG[app.type]
  if (!config) return null

  const IconComponent = config.icon

  return (
    <Col xs={24} sm={12} md={10} lg={8} xl={8}>
      <Card
        hoverable={hasPermission}
        onClick={handleClick}
        className={hasPermission ? styles.applicationCard : styles.blurredCard}
      >
        <Card.Meta
          avatar={<IconComponent style={iconStyle} />}
          description={<CardContent title={config.title} />}
          className="card-meta"
        />
      </Card>
    </Col>
  )
})


function CampaignTools() {
  const { user, handleSignOut, permissions } = usePermissions()
  const [adminPanelVisible, setAdminPanelVisible] = useState(false)
  const [superAdminPanelVisible, setSuperAdminPanelVisible] = useState(false)

  const isAdmin = useMemo(() => user?.displayName === ADMIN_USERNAME, [user?.displayName])
  // Check both email list AND permissions (which includes Firestore isSuperAdmin check)
  const isSuperAdmin = useMemo(() =>
    SUPER_ADMIN_EMAILS.includes(user?.email?.toLowerCase()) || permissions['Manage Database'],
  [user?.email, permissions])

  const openAdminPanel = useCallback(() => setAdminPanelVisible(true), [])
  const closeAdminPanel = useCallback(() => setAdminPanelVisible(false), [])
  const openSuperAdminPanel = useCallback(() => setSuperAdminPanelVisible(true), [])
  const closeSuperAdminPanel = useCallback(() => setSuperAdminPanelVisible(false), [])

  // Memoize the row gutter to prevent object recreation
  const rowGutter = useMemo(() => [16, 16], [])

  return (
    <>
      <CustomHeader />
      <Layout>
        <Sidebar user={user} />
        <Content>
          {user ? (
            <>
              <div className={styles.userContainer}>
                <div className={styles.textContainer}>
                  <Text className={styles.welcomeText}>Welcome, {user.displayName}</Text>
                </div>
                <div className={styles.buttonGroup}>
                  {isSuperAdmin && (
                    <Button
                      className={styles.superAdminButton}
                      icon={<CrownOutlined />}
                      onClick={openSuperAdminPanel}
                    >
                      Super Admin
                    </Button>
                  )}
                  {isAdmin && (
                    <Button
                      className={styles.adminButton}
                      icon={<SafetyOutlined />}
                      onClick={openAdminPanel}
                    >
                      Admin Panel
                    </Button>
                  )}
                  <Button className={styles.actionButton} onClick={handleSignOut}>
                    Logout
                  </Button>
                </div>
              </div>
              <Row gutter={rowGutter} className={styles.rowPadding}>
                {applications.map((app) => (
                  <ApplicationCard key={app.route} app={app} />
                ))}
              </Row>
              <SectionSeparator title="Eigel Campaign Tools" />
              <Row gutter={rowGutter} className={styles.rowPadding}>
                {EigApplications.map((app) => (
                  <EigelApps key={app.route} app={app} />
                ))}
              </Row>
            </>
          ) : (
            <Auth />
          )}
        </Content>
      </Layout>
      <AppFooter />
      {isAdmin && (
        <AdminPanel
          visible={adminPanelVisible}
          onClose={closeAdminPanel}
          currentUser={user}
        />
      )}
      {isSuperAdmin && (
        <SuperAdminPanel
          visible={superAdminPanelVisible}
          onClose={closeSuperAdminPanel}
          currentUser={user}
        />
      )}
    </>
  )
}

export default memo(CampaignTools)
