import { DeleteOutlined, ReloadOutlined, SafetyOutlined, UserOutlined } from '@ant-design/icons'
import { Button, Card, Col, Modal, Popconfirm, Row, Spin, Statistic, Table, Tabs, Tag, Typography, message } from 'antd'
import { collection, deleteField, doc, getDocs, updateDoc, writeBatch, query, orderBy, limit, startAfter } from 'firebase/firestore'
import React, { memo, useCallback, useEffect, useMemo, useState } from 'react'
import { db } from '../auth/firebase.jsx'
import styles from './AdminPanel.module.css'

const { Text, Title } = Typography
const { TabPane } = Tabs

const ADMIN_USERNAME = 'Tony Lonsdale'

// Memoized stat card component
const StatCard = memo(function StatCard({ title, value, prefix, valueStyle }) {
  return (
    <Card>
      <Statistic title={title} value={value} prefix={prefix} valueStyle={valueStyle} />
    </Card>
  )
})

function AdminPanel({ visible, onClose, currentUser }) {
  const [users, setUsers] = useState([])
  const [loading, setLoading] = useState(false)
  const [stats, setStats] = useState({
    totalUsers: 0,
    usersWithPlainTextPasswords: 0,
    administrators: 0,
  })
  const [cleaningPasswords, setCleaningPasswords] = useState(false)

  const isAdmin = currentUser?.displayName === ADMIN_USERNAME

  const fetchUsers = useCallback(async () => {
    if (!isAdmin) return

    setLoading(true)
    try {
      const usersCollection = collection(db, 'users')
      const snapshot = await getDocs(usersCollection)
      const userList = []
      let plainTextCount = 0
      let adminCount = 0

      snapshot.forEach((docSnap) => {
        const data = docSnap.data()
        const hasPlainTextPassword = !!data.password
        if (hasPlainTextPassword) plainTextCount++
        if (data.isAdministrator) adminCount++

        userList.push({
          id: docSnap.id,
          email: data.email || 'N/A',
          username: data.username || 'N/A',
          hasPlainTextPassword,
          isAdministrator: data.isAdministrator || false,
          phoneNumber: data.phoneNumber || null,
          createdAt: data.createdAt || 'Unknown',
        })
      })

      setUsers(userList)
      setStats({
        totalUsers: userList.length,
        usersWithPlainTextPasswords: plainTextCount,
        administrators: adminCount,
      })
    } catch (err) {
      console.error('Error fetching users:', err)
      message.error('Failed to fetch users')
    } finally {
      setLoading(false)
    }
  }, [isAdmin])

  useEffect(() => {
    if (visible && isAdmin) {
      fetchUsers()
    }
  }, [visible, isAdmin, fetchUsers])

  const removePasswordFromUser = useCallback(async (userId) => {
    try {
      const userRef = doc(db, 'users', userId)
      await updateDoc(userRef, {
        password: deleteField(),
      })
      message.success('Plain text password removed')
      fetchUsers()
    } catch (err) {
      console.error('Error removing password:', err)
      message.error('Failed to remove password')
    }
  }, [fetchUsers])

  const cleanAllPlainTextPasswords = useCallback(async () => {
    setCleaningPasswords(true)
    try {
      const usersWithPasswords = users.filter((u) => u.hasPlainTextPassword)

      // Use batch writes for better performance and atomicity (max 500 per batch)
      const batchSize = 500
      let cleaned = 0

      for (let i = 0; i < usersWithPasswords.length; i += batchSize) {
        const batch = writeBatch(db)
        const chunk = usersWithPasswords.slice(i, i + batchSize)

        chunk.forEach((user) => {
          const userRef = doc(db, 'users', user.id)
          batch.update(userRef, { password: deleteField() })
        })

        await batch.commit()
        cleaned += chunk.length
      }

      message.success(`Removed ${cleaned} plain text password(s)`)
      fetchUsers()
    } catch (err) {
      console.error('Error cleaning passwords:', err)
      message.error('Failed to clean passwords')
    } finally {
      setCleaningPasswords(false)
    }
  }, [users, fetchUsers])

  // Memoize columns to prevent table re-renders
  const columns = useMemo(() => [
    {
      title: 'Username',
      dataIndex: 'username',
      key: 'username',
      sorter: (a, b) => a.username.localeCompare(b.username),
    },
    {
      title: 'Email',
      dataIndex: 'email',
      key: 'email',
      sorter: (a, b) => a.email.localeCompare(b.email),
    },
    {
      title: 'Security Status',
      key: 'security',
      render: (_, record) => (
        <>
          {record.hasPlainTextPassword ? (
            <Tag color="red">PLAIN TEXT PASSWORD</Tag>
          ) : (
            <Tag color="green">Secure</Tag>
          )}
          {record.isAdministrator && <Tag color="blue">Admin</Tag>}
        </>
      ),
      filters: [
        { text: 'Has Plain Text Password', value: true },
        { text: 'Secure', value: false },
      ],
      onFilter: (value, record) => record.hasPlainTextPassword === value,
    },
    {
      title: 'Created',
      dataIndex: 'createdAt',
      key: 'createdAt',
      render: (date) => (date !== 'Unknown' ? new Date(date).toLocaleDateString() : 'Unknown'),
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) =>
        record.hasPlainTextPassword ? (
          <Popconfirm
            title="Remove plain text password?"
            description="This will delete the stored password. User can still login via Firebase Auth."
            onConfirm={() => removePasswordFromUser(record.id)}
            okText="Remove"
            cancelText="Cancel"
          >
            <Button type="link" danger icon={<DeleteOutlined />}>
              Remove Password
            </Button>
          </Popconfirm>
        ) : (
          <Text type="secondary">No action needed</Text>
        ),
    },
  ], [removePasswordFromUser])

  if (!isAdmin) {
    return null
  }

  return (
    <Modal
      title={
        <div className={styles.modalTitle}>
          <SafetyOutlined className={styles.titleIcon} />
          <span>Admin Control Panel</span>
        </div>
      }
      open={visible}
      onCancel={onClose}
      footer={null}
      width={1000}
      className={styles.adminModal}
    >
      <Spin spinning={loading}>
        <Tabs defaultActiveKey="overview">
          <TabPane tab="Overview" key="overview">
            <Row gutter={[16, 16]} className={styles.statsRow}>
              <Col span={8}>
                <StatCard
                  title="Total Users"
                  value={stats.totalUsers}
                  prefix={<UserOutlined />}
                />
              </Col>
              <Col span={8}>
                <StatCard
                  title="Security Vulnerabilities"
                  value={stats.usersWithPlainTextPasswords}
                  valueStyle={{ color: stats.usersWithPlainTextPasswords > 0 ? '#cf1322' : '#3f8600' }}
                  prefix={<SafetyOutlined />}
                />
              </Col>
              <Col span={8}>
                <StatCard
                  title="Administrators"
                  value={stats.administrators}
                  prefix={<UserOutlined />}
                />
              </Col>
            </Row>

            {stats.usersWithPlainTextPasswords > 0 && (
              <Card className={styles.warningCard}>
                <Title level={5} type="danger">
                  Security Alert: Plain Text Passwords Detected
                </Title>
                <Text>
                  {stats.usersWithPlainTextPasswords} user(s) have passwords stored in plain text in Firestore.
                  This is a critical security vulnerability. Click below to remove all plain text passwords.
                </Text>
                <div className={styles.actionButtons}>
                  <Popconfirm
                    title="Clean all plain text passwords?"
                    description="This will remove all stored plain text passwords. Users can still login via Firebase Auth."
                    onConfirm={cleanAllPlainTextPasswords}
                    okText="Clean All"
                    cancelText="Cancel"
                  >
                    <Button
                      type="primary"
                      danger
                      icon={<DeleteOutlined />}
                      loading={cleaningPasswords}
                    >
                      Remove All Plain Text Passwords
                    </Button>
                  </Popconfirm>
                </div>
              </Card>
            )}
          </TabPane>

          <TabPane tab="User Management" key="users">
            <div className={styles.tableHeader}>
              <Title level={5}>Registered Users</Title>
              <Button icon={<ReloadOutlined />} onClick={fetchUsers} loading={loading}>
                Refresh
              </Button>
            </div>
            <Table
              columns={columns}
              dataSource={users}
              rowKey="id"
              pagination={{ pageSize: 10 }}
              className={styles.usersTable}
            />
          </TabPane>

          <TabPane tab="Security Log" key="security">
            <Card>
              <Title level={5}>Recent Security Events</Title>
              <Text type="secondary">
                Security logging will track login attempts, password changes, and admin actions.
                This feature monitors session activity and rate limiting events.
              </Text>
              <div className={styles.securityInfo}>
                <Text strong>Current Security Measures:</Text>
                <ul>
                  <li>15-minute session timeout on inactivity</li>
                  <li>5 failed login attempts triggers 15-minute lockout</li>
                  <li>Passwords hashed via Firebase Auth (not stored in Firestore)</li>
                  <li>Session validation via Firebase Functions</li>
                </ul>
              </div>
            </Card>
          </TabPane>
        </Tabs>
      </Spin>
    </Modal>
  )
}

export { ADMIN_USERNAME }
export default memo(AdminPanel)
